	/**
	 * Check whether optional DuckDB query profiling is enabled.
	 *
	 * @return bool Whether profiling is enabled.
	 */
	private static function query_profile_enabled(): bool {
		if ( null === self::$query_profile_enabled ) {
			$value                       = getenv( 'WP_DUCKDB_QUERY_PROFILE' );
			self::$query_profile_enabled = is_string( $value )
				&& '' !== $value
				&& '0' !== $value
				&& 'false' !== strtolower( $value )
				&& 'off' !== strtolower( $value )
				&& 'no' !== strtolower( $value );
		}

		if ( self::$query_profile_enabled && ! self::$query_profile_shutdown_registered ) {
			register_shutdown_function( array( __CLASS__, 'emit_query_profile_shutdown_summary' ) );
			self::$query_profile_shutdown_registered = true;
		}

		return self::$query_profile_enabled;
	}

	/**
	 * Record one MySQL-facing query in the optional profile.
	 *
	 * @param string $query         MySQL query.
	 * @param float  $total_seconds Query wall time.
	 * @param bool   $error         Whether the query ended in an error.
	 */
	private function record_query_profile( string $query, float $total_seconds, bool $error ): void {
		$shape = $this->normalize_query_profile_shape( $query );
		if ( ! isset( self::$query_profile['shapes'][ $shape ] ) ) {
			self::$query_profile['shapes'][ $shape ] = array(
				'count'          => 0,
				'errors'         => 0,
				'total_seconds'  => 0.0,
				'parse_seconds'  => 0.0,
				'native_seconds' => 0.0,
				'native_queries' => 0,
			);
		}

		++self::$query_profile['queries'];
		self::$query_profile['total_seconds']  += $total_seconds;
		self::$query_profile['parse_seconds']  += $this->profile_current_parse_seconds;
		self::$query_profile['native_seconds'] += $this->profile_current_native_seconds;
		self::$query_profile['native_queries'] += $this->profile_current_native_queries;
		if ( $error ) {
			++self::$query_profile['errors'];
		}

		++self::$query_profile['shapes'][ $shape ]['count'];
		self::$query_profile['shapes'][ $shape ]['total_seconds']  += $total_seconds;
		self::$query_profile['shapes'][ $shape ]['parse_seconds']  += $this->profile_current_parse_seconds;
		self::$query_profile['shapes'][ $shape ]['native_seconds'] += $this->profile_current_native_seconds;
		self::$query_profile['shapes'][ $shape ]['native_queries'] += $this->profile_current_native_queries;
		if ( $error ) {
			++self::$query_profile['shapes'][ $shape ]['errors'];
		}

		if ( count( self::$query_profile['shapes'] ) > 1000 && 0 === self::$query_profile['queries'] % 1000 ) {
			self::prune_query_profile_shapes();
		}

		$interval = self::query_profile_log_interval();
		if ( $interval > 0 && 0 === self::$query_profile['queries'] % $interval ) {
			self::emit_query_profile_summary( 'interval' );
		}
	}

	/**
	 * Normalize a query into a bounded, literal-free profile shape.
	 *
	 * @param string $query MySQL query.
	 * @return string Normalized shape.
	 */
	private function normalize_query_profile_shape( string $query ): string {
		$shape = preg_replace( "/'(?:''|\\\\.|[^'\\\\])*'/s", "'?'", $query );
		$shape = preg_replace( '/"(?:\\\\"|\\\\.|[^"\\\\])*"/s', '"?"', (string) $shape );
		$shape = preg_replace( '/\b0x[0-9a-f]+\b/i', '?', (string) $shape );
		$shape = preg_replace( '/\b\d+(?:\.\d+)?\b/', '?', (string) $shape );
		$shape = preg_replace( '/\s+/', ' ', (string) $shape );
		$shape = trim( (string) $shape );

		if ( strlen( $shape ) > 300 ) {
			$shape = substr( $shape, 0, 297 ) . '...';
		}

		return '' === $shape ? '<empty>' : $shape;
	}

	/**
	 * Read the optional profile logging interval.
	 *
	 * @return int Query interval. Zero disables interval logging.
	 */
	private static function query_profile_log_interval(): int {
		$value = getenv( 'WP_DUCKDB_QUERY_PROFILE_INTERVAL' );
		if ( ! is_string( $value ) || '' === $value ) {
			return 5000;
		}

		return max( 0, (int) $value );
	}

	/**
	 * Keep only the highest-cost query shapes when the profiler map grows large.
	 */
	private static function prune_query_profile_shapes(): void {
		$shapes = self::$query_profile['shapes'];
		uasort(
			$shapes,
			function ( array $left, array $right ): int {
				return $right['total_seconds'] <=> $left['total_seconds'];
			}
		);

		self::$query_profile['shapes'] = array_slice( $shapes, 0, 500, true );
	}

	/**
	 * Emit the optional profile at PHP shutdown.
	 */
	public static function emit_query_profile_shutdown_summary(): void {
		self::emit_query_profile_summary( 'shutdown' );
	}

	/**
	 * Emit an optional profiler summary to the PHP error log.
	 *
	 * @param string $reason Why the summary is being emitted.
	 */
	private static function emit_query_profile_summary( string $reason ): void {
		if ( ! self::query_profile_enabled() || 0 === self::$query_profile['queries'] ) {
			return;
		}

		error_log(
			sprintf(
				'WP_DUCKDB_QUERY_PROFILE_SUMMARY reason=%s queries=%d errors=%d total_seconds=%.3f parse_seconds=%.3f native_seconds=%.3f native_queries=%d shapes=%d',
				$reason,
				self::$query_profile['queries'],
				self::$query_profile['errors'],
				self::$query_profile['total_seconds'],
				self::$query_profile['parse_seconds'],
				self::$query_profile['native_seconds'],
				self::$query_profile['native_queries'],
				count( self::$query_profile['shapes'] )
			)
		);

		$shapes = self::$query_profile['shapes'];
		uasort(
			$shapes,
			function ( array $left, array $right ): int {
				return $right['total_seconds'] <=> $left['total_seconds'];
			}
		);

		$rank = 0;
		foreach ( array_slice( $shapes, 0, 15, true ) as $shape => $profile ) {
			++$rank;
			error_log(
				sprintf(
					'WP_DUCKDB_QUERY_PROFILE_TOP rank=%d count=%d errors=%d total_seconds=%.3f avg_ms=%.3f parse_seconds=%.3f native_seconds=%.3f native_queries=%d shape=%s',
					$rank,
					$profile['count'],
					$profile['errors'],
					$profile['total_seconds'],
					1000 * $profile['total_seconds'] / max( 1, $profile['count'] ),
					$profile['parse_seconds'],
					$profile['native_seconds'],
					$profile['native_queries'],
					str_replace( array( "\r", "\n" ), ' ', $shape )
				)
			);
		}
	}

	/**
	 * Return a cache key for a metadata table ensure operation.
	 *
	 * @param string $kind      Metadata table kind.
	 * @param bool   $temporary Whether to use session-local temporary metadata.
	 * @return string Cache key.
	 */
	private function metadata_ensure_key( string $kind, bool $temporary ): string {
		return ( $temporary ? 'temporary:' : 'persistent:' ) . $kind;
	}

	/**
	 * Return a cache key for table-scoped metadata.
	 *
	 * @param string $table_name Table name.
	 * @param bool   $temporary  Whether to use session-local temporary metadata.
	 * @return string Cache key.
	 */
	private function metadata_table_cache_key( string $table_name, bool $temporary ): string {
		return $this->metadata_ensure_key( strtolower( $table_name ), $temporary );
	}

	/**
	 * Clear cached schema metadata and metadata-table ensure state after rollback.
	 */
	private function clear_schema_state_after_rollback(): void {
		$this->clear_schema_metadata_cache();
		$this->clear_metadata_table_ensure_cache();
	}

	/**
	 * Clear cached internal metadata table ensure state.
	 *
	 * @param bool|null $temporary Optional metadata table set to clear.
	 */
	private function clear_metadata_table_ensure_cache( ?bool $temporary = null ): void {
		if ( null === $temporary ) {
			$this->ensured_metadata_tables = array();
			return;
		}

		$prefix = $temporary ? 'temporary:' : 'persistent:';
		foreach ( array_keys( $this->ensured_metadata_tables ) as $ensure_key ) {
			if ( 0 === strpos( $ensure_key, $prefix ) ) {
				unset( $this->ensured_metadata_tables[ $ensure_key ] );
			}
		}
	}

	/**
	 * Clear cached schema metadata after DDL or metadata table writes.
	 *
	 * @param string|null $table_name Optional table name whose table-scoped metadata changed.
	 * @param bool|null   $temporary  Optional table set whose metadata changed.
	 */
	private function clear_schema_metadata_cache( ?string $table_name = null, ?bool $temporary = null ): void {
		if ( null === $table_name ) {
			$this->table_name_cache              = array();
			$this->table_metadata_cache          = array();
			$this->column_metadata_cache         = array();
			$this->table_column_metadata_cache   = array();
			$this->auto_increment_metadata_cache = array();
			$this->primary_key_index_rows_cache  = array();
			$this->unique_key_column_sets_cache  = array();
			return;
		}

		unset( $this->primary_key_index_rows_cache[ $this->metadata_table_cache_key( $table_name, false ) ] );

		$sets = null === $temporary ? array( false, true ) : array( $temporary );
		foreach ( $sets as $temporary_set ) {
			$key = $this->metadata_table_cache_key( $table_name, $temporary_set );
			unset(
				$this->column_metadata_cache[ $key ],
				$this->table_column_metadata_cache[ $key ],
				$this->auto_increment_metadata_cache[ $key ],
				$this->unique_key_column_sets_cache[ $key ]
			);

			$table_set_key = $this->metadata_ensure_key( 'tables', $temporary_set );
			unset(
				$this->table_name_cache[ $table_set_key ],
				$this->table_metadata_cache[ $table_set_key ]
			);
		}
	}

	/**
	 * Return the metadata table that stores secondary index rows.
	 *
	 * @param bool $temporary Whether to use session-local temporary metadata.
	 * @return string Metadata table name.
	 */
	private function index_metadata_table_name( bool $temporary ): string {
		return $temporary ? self::TEMP_INDEX_METADATA_TABLE : self::INDEX_METADATA_TABLE;
	}

	/**
	 * Return the metadata table that stores column rows.
	 *
	 * @param bool $temporary Whether to use session-local temporary metadata.
	 * @return string Metadata table name.
	 */
	private function column_metadata_table_name( bool $temporary ): string {
		return $temporary ? self::TEMP_COLUMN_METADATA_TABLE : self::COLUMN_METADATA_TABLE;
	}

	/**
	 * Return the metadata table that stores table rows.
	 *
	 * @param bool $temporary Whether to use session-local temporary metadata.
	 * @return string Metadata table name.
	 */
	private function table_metadata_table_name( bool $temporary ): string {
		return $temporary ? self::TEMP_TABLE_METADATA_TABLE : self::TABLE_METADATA_TABLE;
	}

	/**
	 * Return the metadata table that stores CHECK constraint rows.
	 *
	 * @param bool $temporary Whether to use session-local temporary metadata.
	 * @return string Metadata table name.
	 */
	private function check_metadata_table_name( bool $temporary ): string {
		return $temporary ? self::TEMP_CHECK_METADATA_TABLE : self::CHECK_METADATA_TABLE;
	}

	/**
	 * Return the metadata table that stores FOREIGN KEY constraint rows.
	 *
	 * @param bool $temporary Whether to use session-local temporary metadata.
	 * @return string Metadata table name.
	 */
	private function foreign_key_metadata_table_name( bool $temporary ): string {
		return $temporary ? self::TEMP_FOREIGN_KEY_METADATA_TABLE : self::FOREIGN_KEY_METADATA_TABLE;
	}

	/**
	 * Insert rows whose values have already been quoted or otherwise rendered as SQL.
	 *
	 * @param string                       $table_name    Table name.
	 * @param array<int,string>            $columns       Column names.
	 * @param array<int,array<int,string>> $value_rows    Pre-rendered SQL value rows.
	 * @param string                       $error_message Error message for failed inserts.
	 */
	private function insert_rendered_value_rows( string $table_name, array $columns, array $value_rows, string $error_message ): void {
		if ( count( $value_rows ) === 0 ) {
			return;
		}

		$quoted_columns = array();
		foreach ( $columns as $column_name ) {
			$quoted_columns[] = $this->connection->quote_identifier( $column_name );
		}

		$tuples = array();
		foreach ( $value_rows as $values ) {
			$tuples[] = '(' . implode( ', ', $values ) . ')';
		}

		$this->execute_duckdb_query(
			'INSERT INTO '
				. $this->connection->quote_identifier( $table_name )
				. ' ('
				. implode( ', ', $quoted_columns )
				. ') VALUES '
				. implode( ', ', $tuples ),
			$error_message
		);
	}

	/**
	 * Record MySQL index metadata for SHOW INDEX.
	 *
	 * @param array{table_name:string,index_name:string,unique:bool,temporary?:bool,index_type?:string,columns:array<int,array{name:string,sub_part:int|null}>} $index_definition Index definition.
	 */
	private function record_index_metadata( array $index_definition ): void {
		$temporary = isset( $index_definition['temporary'] ) && (bool) $index_definition['temporary'];
		$this->ensure_index_metadata_table( $temporary );

		$table_name = $index_definition['table_name'];
		$index_name = $index_definition['index_name'];
		$index_type = $index_definition['index_type'] ?? 'BTREE';

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->index_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' AND index_name = '
				. $this->connection->quote( $index_name ),
			'Failed to reset DuckDB index metadata'
		);

		$value_rows = array();
		foreach ( $index_definition['columns'] as $offset => $column ) {
			$value_rows[] = array(
				$this->connection->quote( $table_name ),
				$this->connection->quote( $index_name ),
				$index_definition['unique'] ? '0' : '1',
				(string) ( $offset + 1 ),
				$this->connection->quote( $column['name'] ),
				$this->connection->quote( $column['sub_part'] ),
				$this->connection->quote( $index_type ),
			);
		}

		$this->insert_rendered_value_rows(
			$this->index_metadata_table_name( $temporary ),
			array( 'table_name', 'index_name', 'non_unique', 'seq_in_index', 'column_name', 'sub_part', 'index_type' ),
			$value_rows,
			'Failed to store DuckDB index metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Execute a schema change while temporarily dropping secondary indexes.
	 *
	 * @param string   $table_name Table name.
	 * @param callable $callback   Schema change callback.
	 */
	private function execute_with_secondary_indexes_rebuilt( string $table_name, callable $callback, bool $temporary = false ): void {
		$index_definitions = $this->secondary_index_definitions_for_table( $table_name, $temporary );
		foreach ( $index_definitions as $index_definition ) {
			$this->execute_duckdb_query(
				'DROP INDEX IF EXISTS ' . $this->connection->quote_identifier( $this->index_name( $table_name, $index_definition['index_name'], $temporary ) ),
				'Failed to drop DuckDB index before schema change'
			);
		}

		$exception = null;
		try {
			$callback();
		} catch ( Throwable $e ) {
			$exception = $e;
		}

		foreach ( $index_definitions as $index_definition ) {
			$this->execute_duckdb_query( $index_definition['sql'], 'Failed to recreate DuckDB index after schema change' );
			$this->record_index_metadata( $index_definition );
		}

		if ( null !== $exception ) {
			throw $exception;
		}
	}

	/**
	 * Read recorded secondary index definitions for a table.
	 *
	 * @param string $table_name Table name.
	 * @return array<int,array{sql:string,table_name:string,index_name:string,unique:bool,index_type:string,columns:array<int,array{name:string,sub_part:int|null}>}>
	 */
	private function secondary_index_definitions_for_table( string $table_name, bool $temporary = false ): array {
		$this->ensure_index_metadata_table( $temporary );

		$stmt = $this->execute_duckdb_query(
			'SELECT index_name, non_unique, seq_in_index, column_name, sub_part, index_type FROM '
				. $this->connection->quote_identifier( $this->index_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' ORDER BY index_name, seq_in_index',
			'Failed to inspect DuckDB secondary indexes'
		);

		$grouped = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$index_name = (string) $row['index_name'];
			if ( ! isset( $grouped[ $index_name ] ) ) {
				$grouped[ $index_name ] = array(
					'unique'     => 0 === (int) $row['non_unique'],
					'index_type' => null === $row['index_type'] ? 'BTREE' : (string) $row['index_type'],
					'columns'    => array(),
				);
			}
			$grouped[ $index_name ]['columns'][] = array(
				'name'     => (string) $row['column_name'],
				'sub_part' => null === $row['sub_part'] ? null : (int) $row['sub_part'],
			);
		}

		$definitions = array();
		foreach ( $grouped as $index_name => $definition ) {
			$definitions[] = $this->build_secondary_index_definition(
				$table_name,
				$index_name,
				$definition['unique'],
				array_map(
					function ( array $column ): string {
						return $this->connection->quote_identifier( $column['name'] );
					},
					$definition['columns']
				),
				$definition['columns'],
				$temporary,
				$definition['index_type']
			);
		}

		return $definitions;
	}

	/**
	 * Record MySQL column metadata for DESCRIBE and SHOW COLUMNS.
	 *
	 * @param string                         $table_name Table name.
	 * @param array<int,array<string,mixed>> $metadata   Column metadata.
	 */
	private function record_column_metadata( string $table_name, array $metadata, bool $temporary = false ): void {
		$this->ensure_column_metadata_table( $temporary );

		$this->execute_column_metadata_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->column_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to reset DuckDB column metadata',
			$temporary
		);

		$value_rows = array();
		foreach ( $metadata as $offset => $column ) {
			$value_rows[] = array(
				$this->connection->quote( $table_name ),
				(string) ( $offset + 1 ),
				$this->connection->quote( $column['column_name'] ),
				$this->connection->quote( $column['column_type'] ),
				$this->connection->quote( $column['is_nullable'] ),
				$this->connection->quote( $column['column_key'] ),
				$this->connection->quote( $column['column_default'] ),
				$this->connection->quote( $column['extra'] ),
				$this->connection->quote( $column['collation_name'] ),
				$this->connection->quote( $column['comment'] ),
			);
		}

		$this->insert_rendered_value_rows(
			$this->column_metadata_table_name( $temporary ),
			array(
				'table_name',
				'ordinal_position',
				'column_name',
				'column_type',
				'is_nullable',
				'column_key',
				'column_default',
				'extra',
				'collation_name',
				'comment',
			),
			$value_rows,
			'Failed to store DuckDB column metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Execute a column metadata query, repairing stale ensure cache if DuckDB lost the internal metadata table.
	 *
	 * @param string $sql       DuckDB SQL.
	 * @param string $context   Error context.
	 * @param bool   $temporary Whether the metadata table is temporary.
	 * @return WP_DuckDB_Result_Statement
	 */
	private function execute_column_metadata_query( string $sql, string $context, bool $temporary ): WP_DuckDB_Result_Statement {
		try {
			return $this->execute_duckdb_query( $sql, $context );
		} catch ( WP_DuckDB_Driver_Exception $e ) {
			if ( ! $this->is_missing_internal_metadata_table_exception( $e, $this->column_metadata_table_name( $temporary ) ) ) {
				throw $e;
			}

			$this->clear_metadata_table_ensure_cache( $temporary );
			$this->column_metadata_cache       = array();
			$this->table_column_metadata_cache = array();
			$this->ensure_column_metadata_table( $temporary );

			return $this->execute_duckdb_query( $sql, $context );
		}
	}

	/**
	 * Check whether a DuckDB exception reports a missing internal metadata table.
	 *
	 * @param WP_DuckDB_Driver_Exception $exception      Driver exception.
	 * @param string                     $metadata_table Internal metadata table name.
	 * @return bool Whether the exception is a missing metadata table error.
	 */
	private function is_missing_internal_metadata_table_exception( WP_DuckDB_Driver_Exception $exception, string $metadata_table ): bool {
		$message = $exception->getMessage();
		if ( false === strpos( $message, $metadata_table ) ) {
			return false;
		}

		return false !== stripos( $message, 'does not exist' )
			|| false !== stripos( $message, 'not found' );
	}

	/**
	 * Record MySQL table metadata for information_schema.tables.
	 *
	 * @param string              $table_name Table name.
	 * @param array<string,mixed> $metadata   Table metadata.
	 */
	private function record_table_metadata( string $table_name, array $metadata, bool $temporary = false ): void {
		$this->ensure_table_metadata_table( $temporary );

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->table_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to reset DuckDB table metadata'
		);

		$this->execute_duckdb_query(
			'INSERT INTO '
				. $this->connection->quote_identifier( $this->table_metadata_table_name( $temporary ) )
				. ' (table_name, engine, row_format, table_collation, table_comment, create_options, create_time) VALUES ('
				. $this->connection->quote( $table_name )
				. ', '
				. $this->connection->quote( $metadata['engine'] )
				. ', '
				. $this->connection->quote( $metadata['row_format'] )
				. ', '
				. $this->connection->quote( $metadata['table_collation'] )
				. ', '
				. $this->connection->quote( $metadata['table_comment'] )
				. ', '
				. $this->connection->quote( $metadata['create_options'] )
				. ', '
				. $this->connection->quote( gmdate( 'Y-m-d H:i:s' ) )
				. ')',
			'Failed to store DuckDB table metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Record MySQL CHECK constraint metadata for SHOW CREATE TABLE.
	 *
	 * @param string                  $table_name Table name.
	 * @param array<int,array<string,string>> $metadata   CHECK metadata rows.
	 * @param bool                    $temporary  Whether the target is a temporary table.
	 */
	private function record_check_metadata( string $table_name, array $metadata, bool $temporary = false ): void {
		$this->ensure_check_metadata_table( $temporary );

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->check_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to reset DuckDB CHECK constraint metadata'
		);

		$value_rows = array();
		foreach ( $metadata as $constraint ) {
			$value_rows[] = array(
				$this->connection->quote( $table_name ),
				$this->connection->quote( $constraint['constraint_name'] ),
				$this->connection->quote( $constraint['check_clause'] ),
				$this->connection->quote( $constraint['enforced'] ),
			);
		}

		$this->insert_rendered_value_rows(
			$this->check_metadata_table_name( $temporary ),
			array( 'table_name', 'constraint_name', 'check_clause', 'enforced' ),
			$value_rows,
			'Failed to store DuckDB CHECK constraint metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Record MySQL FOREIGN KEY constraint metadata.
	 *
	 * @param string                         $table_name Table name.
	 * @param array<int,array<string,mixed>> $metadata   FOREIGN KEY metadata rows.
	 * @param bool                           $temporary  Whether the target is a temporary table.
	 */
	private function record_foreign_key_metadata( string $table_name, array $metadata, bool $temporary = false ): void {
		$this->ensure_foreign_key_metadata_table( $temporary );

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->foreign_key_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to reset DuckDB FOREIGN KEY metadata'
		);

		$value_rows = array();
		foreach ( $metadata as $constraint ) {
			foreach ( $constraint['columns'] as $offset => $column_name ) {
				$value_rows[] = array(
					$this->connection->quote( $table_name ),
					$this->connection->quote( $constraint['constraint_name'] ),
					(string) ( $offset + 1 ),
					$this->connection->quote( $column_name ),
					$this->connection->quote( $constraint['referenced_table_name'] ),
					$this->connection->quote( $constraint['referenced_columns'][ $offset ] ),
					$this->connection->quote( $constraint['update_rule'] ),
					$this->connection->quote( $constraint['delete_rule'] ),
				);
			}
		}

		$this->insert_rendered_value_rows(
			$this->foreign_key_metadata_table_name( $temporary ),
			array(
				'table_name',
				'constraint_name',
				'ordinal_position',
				'column_name',
				'referenced_table_name',
				'referenced_column_name',
				'update_rule',
				'delete_rule',
			),
			$value_rows,
			'Failed to store DuckDB FOREIGN KEY metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Read recorded MySQL CHECK constraint metadata.
	 *
	 * @param string $table_name Table name.
	 * @param bool   $temporary  Whether to use session-local temporary metadata.
	 * @return array<int,array<string,mixed>>
	 */
	private function check_constraint_metadata_rows( string $table_name, bool $temporary = false ): array {
		$this->ensure_check_metadata_table( $temporary );

		$stmt = $this->execute_duckdb_query(
			'SELECT constraint_name, check_clause, enforced FROM '
				. $this->connection->quote_identifier( $this->check_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' ORDER BY constraint_name',
			'Failed to inspect DuckDB CHECK constraint metadata'
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Read recorded MySQL FOREIGN KEY constraint metadata.
	 *
	 * @param string $table_name Table name.
	 * @param bool   $temporary  Whether to use session-local temporary metadata.
	 * @return array<int,array<string,mixed>>
	 */
	private function foreign_key_metadata_rows( string $table_name, bool $temporary = false ): array {
		$this->ensure_foreign_key_metadata_table( $temporary );

		$stmt = $this->execute_duckdb_query(
			'SELECT constraint_name, ordinal_position, column_name, referenced_table_name, referenced_column_name, update_rule, delete_rule FROM '
				. $this->connection->quote_identifier( $this->foreign_key_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' ORDER BY constraint_name, ordinal_position',
			'Failed to inspect DuckDB FOREIGN KEY metadata'
		);

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

	/**
	 * Append one MySQL column metadata row when full table metadata is already recorded.
	 *
	 * @param string              $table_name Table name.
	 * @param array<string,mixed> $column     Column metadata.
	 */
	private function append_column_metadata( string $table_name, array $column, bool $temporary = false ): void {
		$this->ensure_column_metadata_table( $temporary );

		$stmt = $this->execute_column_metadata_query(
			'SELECT COUNT(*) AS column_count, COALESCE(MAX(ordinal_position), 0) AS max_ordinal FROM '
				. $this->connection->quote_identifier( $this->column_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to inspect DuckDB column metadata',
			$temporary
		);
		$row  = $stmt->fetch( PDO::FETCH_ASSOC );
		if ( ! is_array( $row ) || 0 === (int) $row['column_count'] ) {
			return;
		}

		$this->execute_column_metadata_query(
			'INSERT INTO '
				. $this->connection->quote_identifier( $this->column_metadata_table_name( $temporary ) )
				. ' (table_name, ordinal_position, column_name, column_type, is_nullable, column_key, column_default, extra, collation_name, comment) VALUES ('
				. $this->connection->quote( $table_name )
				. ', '
				. ( (int) $row['max_ordinal'] + 1 )
				. ', '
				. $this->connection->quote( $column['column_name'] )
				. ', '
				. $this->connection->quote( $column['column_type'] )
				. ', '
				. $this->connection->quote( $column['is_nullable'] )
				. ', '
				. $this->connection->quote( $column['column_key'] )
				. ', '
				. $this->connection->quote( $column['column_default'] )
				. ', '
				. $this->connection->quote( $column['extra'] )
				. ', '
				. $this->connection->quote( $column['collation_name'] )
				. ', '
				. $this->connection->quote( $column['comment'] )
				. ')',
			'Failed to store DuckDB column metadata',
			$temporary
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Drop a recorded secondary index and refresh MySQL-facing metadata.
	 *
	 * @param string $table_name       Table name.
	 * @param string $mysql_index_name MySQL-facing index name.
	 */
	private function drop_secondary_index( string $table_name, string $mysql_index_name, bool $temporary = false ): void {
		if ( 0 === strcasecmp( $mysql_index_name, 'PRIMARY' ) ) {
			throw new WP_DuckDB_Driver_Exception( 'Unsupported DROP INDEX statement in DuckDB driver. Dropping PRIMARY requires a table rebuild.' );
		}

		$resolved_index_name = $this->resolve_secondary_index_name( $table_name, $mysql_index_name, $temporary );
		if ( null === $resolved_index_name ) {
			throw new WP_DuckDB_Driver_Exception( "Unknown index '{$mysql_index_name}' on table '{$this->database}.{$table_name}' in DuckDB driver." );
		}

		$this->drop_physical_secondary_index( $table_name, $resolved_index_name, false, $temporary );
		$this->delete_index_metadata( $table_name, $resolved_index_name, $temporary );
		$this->refresh_column_key_metadata( $table_name, $temporary );
	}

	/**
	 * Resolve a secondary index name from recorded metadata.
	 *
	 * @param string $table_name       Table name.
	 * @param string $mysql_index_name Requested index name.
	 * @return string|null Resolved index name.
	 */
	private function resolve_secondary_index_name( string $table_name, string $mysql_index_name, bool $temporary = false ): ?string {
		foreach ( $this->secondary_index_definitions_for_table( $table_name, $temporary ) as $index_definition ) {
			if ( 0 === strcasecmp( $index_definition['index_name'], $mysql_index_name ) ) {
				return $index_definition['index_name'];
			}
		}

		return null;
	}

	/**
	 * Resolve a single-column UNIQUE secondary index by column name.
	 *
	 * @param string $table_name  Table name.
	 * @param string $column_name Column name.
	 * @param bool   $temporary   Whether the target table is temporary.
	 * @return string|null MySQL-facing index name when a full-column unique index matches.
	 */
	private function single_column_unique_secondary_index_name( string $table_name, string $column_name, bool $temporary = false ): ?string {
		foreach ( $this->secondary_index_definitions_for_table( $table_name, $temporary ) as $index_definition ) {
			if ( ! $index_definition['unique'] || 1 !== count( $index_definition['columns'] ) ) {
				continue;
			}

			$column = $index_definition['columns'][0];
			if ( null !== $column['sub_part'] ) {
				continue;
			}

			if ( 0 === strcasecmp( (string) $column['name'], $column_name ) ) {
				return (string) $index_definition['index_name'];
			}
		}

		return null;
	}

	/**
	 * Reject duplicate secondary index names before CREATE INDEX IF NOT EXISTS can drift metadata.
	 *
	 * @param string $table_name       Table name.
	 * @param string $mysql_index_name MySQL-facing index name.
	 * @param bool   $temporary        Whether the target is a temporary table.
	 */
	private function assert_secondary_index_name_available( string $table_name, string $mysql_index_name, bool $temporary = false ): void {
		if ( null !== $this->resolve_secondary_index_name( $table_name, $mysql_index_name, $temporary ) ) {
			throw new WP_DuckDB_Driver_Exception( "Duplicate key name '{$mysql_index_name}' on table '{$this->database}.{$table_name}' in DuckDB driver." );
		}
	}

	/**
	 * Reject unknown or repeated secondary-index columns before mutating physical indexes.
	 *
	 * @param string                                                                 $table_name       Table name.
	 * @param array{columns:array<int,array{name:string,sub_part:int|null}>}          $index_definition Planned index definition.
	 * @param string                                                                 $context          Error context.
	 * @param bool                                                                   $temporary        Whether the target is a temporary table.
	 */
	private function assert_secondary_index_columns_exist( string $table_name, array $index_definition, string $context, bool $temporary = false ): void {
		$metadata_by_column = array();
		foreach ( $this->table_column_metadata_rows( $table_name, $temporary ) as $column ) {
			$metadata_by_column[ strtolower( (string) $column['column_name'] ) ] = true;
		}

		$seen_columns = array();
		foreach ( $index_definition['columns'] as $column ) {
			$column_name            = (string) $column['name'];
			$normalized_column_name = strtolower( $column_name );

			if ( isset( $seen_columns[ $normalized_column_name ] ) ) {
				throw new WP_DuckDB_Driver_Exception( "Duplicate column name '{$column_name}' in {$context}." );
			}
			$seen_columns[ $normalized_column_name ] = true;

			if ( ! isset( $metadata_by_column[ $normalized_column_name ] ) ) {
				throw new WP_DuckDB_Driver_Exception( "Unknown column '{$column_name}' on table '{$this->database}.{$table_name}' in {$context}." );
			}
		}
	}

	/**
	 * Drop a physical DuckDB secondary index by its MySQL-facing name.
	 *
	 * @param string $table_name       Table name.
	 * @param string $mysql_index_name MySQL-facing index name.
	 * @param bool   $if_exists        Whether to use IF EXISTS.
	 */
	private function drop_physical_secondary_index( string $table_name, string $mysql_index_name, bool $if_exists, bool $temporary = false ): void {
		$this->execute_duckdb_query(
			'DROP INDEX '
				. ( $if_exists ? 'IF EXISTS ' : '' )
				. $this->connection->quote_identifier( $this->index_name( $table_name, $mysql_index_name, $temporary ) ),
			'Failed to drop DuckDB index'
		);
	}

	/**
	 * Delete one secondary index's metadata rows.
	 *
	 * @param string $table_name Table name.
	 * @param string $index_name Index name.
	 */
	private function delete_index_metadata( string $table_name, string $index_name, bool $temporary = false ): void {
		$this->ensure_index_metadata_table( $temporary );

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->index_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' AND index_name = '
				. $this->connection->quote( $index_name ),
			'Failed to delete DuckDB index metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Delete all secondary index metadata rows for a table.
	 *
	 * @param string $table_name Table name.
	 * @param bool   $temporary  Whether the target is a temporary table.
	 */
	private function delete_index_metadata_for_table( string $table_name, bool $temporary = false ): void {
		$this->ensure_index_metadata_table( $temporary );

		$this->execute_duckdb_query(
			'DELETE FROM '
				. $this->connection->quote_identifier( $this->index_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name ),
			'Failed to delete DuckDB table index metadata'
		);

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Delete all stored lifecycle metadata for a table.
	 *
	 * @param string $table_name Table name.
	 */
	private function delete_table_lifecycle_metadata( string $table_name, bool $temporary = false ): void {
		$this->ensure_index_metadata_table( $temporary );
		$this->ensure_column_metadata_table( $temporary );
		$this->ensure_table_metadata_table( $temporary );
		$this->ensure_check_metadata_table( $temporary );
		$this->ensure_foreign_key_metadata_table( $temporary );

		$metadata_tables = array(
			$this->index_metadata_table_name( $temporary ) => 'index',
			$this->column_metadata_table_name( $temporary ) => 'column',
			$this->table_metadata_table_name( $temporary ) => 'table',
			$this->check_metadata_table_name( $temporary ) => 'CHECK constraint',
			$this->foreign_key_metadata_table_name( $temporary ) => 'FOREIGN KEY',
		);

		foreach ( $metadata_tables as $metadata_table => $label ) {
			$sql     = 'DELETE FROM '
				. $this->connection->quote_identifier( $metadata_table )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name );
			$context = 'Failed to delete DuckDB ' . $label . ' metadata';

			if ( $this->column_metadata_table_name( $temporary ) === $metadata_table ) {
				$this->execute_column_metadata_query( $sql, $context, $temporary );
			} else {
				$this->execute_duckdb_query( $sql, $context );
			}
		}

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Refresh stored COLUMN_KEY values after index metadata changes.
	 *
	 * @param string $table_name Table name.
	 */
	private function refresh_column_key_metadata( string $table_name, bool $temporary = false ): void {
		$metadata = $this->column_metadata_rows( $table_name, $temporary );
		if ( count( $metadata ) === 0 ) {
			return;
		}

		foreach ( $metadata as &$column ) {
			$column['column_key'] = '';
		}
		unset( $column );

		$primary_key = array_map(
			function ( array $row ): string {
				return (string) $row[4];
			},
			$this->primary_key_index_rows( $table_name )
		);

		$metadata_table = $this->connection->quote_identifier( $this->column_metadata_table_name( $temporary ) );
		$metadata       = $this->apply_column_key_metadata(
			$metadata,
			$primary_key,
			$this->secondary_index_definitions_for_table( $table_name, $temporary )
		);

		foreach ( $metadata as $column ) {
			$this->execute_column_metadata_query(
				'UPDATE '
					. $metadata_table
					. ' SET column_key = '
					. $this->connection->quote( $column['column_key'] )
					. ' WHERE table_name = '
					. $this->connection->quote( $table_name )
					. ' AND column_name = '
					. $this->connection->quote( $column['column_name'] ),
				'Failed to refresh DuckDB column metadata',
				$temporary
			);
		}

		$this->clear_schema_metadata_cache( $table_name, $temporary );
	}

	/**
	 * Rebuild an empty table so AUTO_INCREMENT starts from 1 again.
	 *
	 * DuckDB cannot restart a sequence while a column default depends on it.
	 *
	 * @param string $table_name Table name.
	 */
	private function rebuild_empty_auto_increment_table( string $table_name, bool $temporary = false ): void {
		$create_sql     = $this->mysql_create_table_statement( $table_name, $table_name, $temporary, 1 );
		$sequence_names = $this->auto_increment_sequences_for_table( $table_name, $temporary );

		$this->execute_duckdb_query(
			'DROP TABLE ' . $this->connection->quote_identifier( $table_name ),
			'Failed to truncate DuckDB table'
		);
		$this->drop_auto_increment_sequences( $sequence_names );
		$this->execute_create_table( $this->tokenize_and_validate( $create_sql ) );
	}

	/**
	 * Rebuild a table so its AUTO_INCREMENT sequence has a specific next value.
	 *
	 * @param string $table_name Table name.
	 * @param int    $next_value Desired next generated value.
	 * @param bool   $temporary  Whether the target is a temporary table.
	 */
	private function rebuild_auto_increment_table_with_next_value( string $table_name, int $next_value, bool $temporary = false ): void {
		$this->rebuild_table_from_metadata_plan(
			$table_name,
			$this->table_column_metadata_rows( $table_name, $temporary ),
			$this->primary_key_columns_for_table( $table_name ),
			$this->secondary_index_definitions_for_table( $table_name, $temporary ),
			$this->check_constraint_metadata_rows( $table_name, $temporary ),
			$this->show_create_table_foreign_key_groups( $table_name, $temporary ),
			$next_value,
			'AUTO_INCREMENT',
			$temporary
		);
	}

	/**
	 * Drop temporary information_schema compatibility snapshots.
	 */
	private function invalidate_information_schema_compatibility_tables(): void {
		$this->clear_schema_metadata_cache();

		foreach (
			array(
				self::INFO_SCHEMA_TABLES_TABLE,
				self::INFO_SCHEMA_COLUMNS_TABLE,
				self::INFO_SCHEMA_STATISTICS_TABLE,
				self::INFO_SCHEMA_TABLE_CONSTRAINTS_TABLE,
				self::INFO_SCHEMA_KEY_COLUMN_USAGE_TABLE,
				self::INFO_SCHEMA_REFERENTIAL_CONSTRAINTS_TABLE,
				self::INFO_SCHEMA_CHECK_CONSTRAINTS_TABLE,
			) as $table_name
		) {
			$this->execute_duckdb_query(
				'DROP TABLE IF EXISTS ' . $this->connection->quote_identifier( $table_name ),
				'Failed to invalidate DuckDB information_schema compatibility table'
			);
		}
	}

	/**
	 * Check whether the current database is information_schema.
	 *
	 * @return bool Whether information_schema is selected.
	 */
	private function is_information_schema_current_database(): bool {
		return 0 === strcasecmp( $this->current_database, 'information_schema' );
	}

	/**
	 * Build a stable information_schema access-denied exception.
	 *
	 * @return WP_DuckDB_Driver_Exception Exception.
	 */
	private function new_information_schema_access_denied_exception(): WP_DuckDB_Driver_Exception {
		return new WP_DuckDB_Driver_Exception( "Access denied for user 'duckdb'@'%' to database 'information_schema'" );
	}

	/**
	 * Assert that an unqualified write target is not implicitly information_schema.
	 */
	private function assert_unqualified_write_allowed_in_current_database(): void {
		if ( $this->is_information_schema_current_database() ) {
			throw $this->new_information_schema_access_denied_exception();
		}
	}

	/**
	 * Check whether a token is an identifier with the requested value.
	 *
	 * @param WP_Parser_Token|null $token      Token.
	 * @param string               $identifier Identifier value.
	 * @return bool Whether the token matches.
	 */
	private function token_identifier_equals( $token, string $identifier ): bool {
		return $token instanceof WP_Parser_Token
			&& ! $this->is_non_identifier_token( $token )
			&& 0 === strcasecmp( $token->get_value(), $identifier );
	}

	/**
	 * Return the token count for a reference to an information_schema table.
	 *
	 * @param WP_Parser_Token[] $tokens     Token stream.
	 * @param int               $index      Token offset.
	 * @param string            $table_name information_schema table name.
	 * @return int|null Token count, or null when there is no reference.
	 */
	private function information_schema_reference_length( array $tokens, int $index, string $table_name ): ?int {
		if (
			isset( $tokens[ $index + 2 ] )
			&& $this->token_identifier_equals( $tokens[ $index ], 'information_schema' )
			&& WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $index + 1 ]->id
			&& $this->token_identifier_equals( $tokens[ $index + 2 ], $table_name )
		) {
			return 3;
		}

		if (
			$this->is_information_schema_current_database()
			&& $this->token_identifier_equals( $tokens[ $index ] ?? null, $table_name )
			&& $this->is_unqualified_information_schema_table_reference_context( $tokens, $index )
		) {
			return 1;
		}

		return null;
	}

	/**
	 * Check whether an unqualified token appears in a table-reference position.
	 *
	 * @param WP_Parser_Token[] $tokens Token stream.
	 * @param int               $index  Token offset.
	 * @return bool Whether this position can be an unqualified table reference.
	 */
	private function is_unqualified_information_schema_table_reference_context( array $tokens, int $index ): bool {
		if (
			( isset( $tokens[ $index - 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $index - 1 ]->id )
			|| ( isset( $tokens[ $index + 1 ] ) && WP_MySQL_Lexer::DOT_SYMBOL === $tokens[ $index + 1 ]->id )
		) {
			return false;
		}

		if ( ! isset( $tokens[ $index - 1 ] ) ) {
			return false;
		}

		return in_array(
			$tokens[ $index - 1 ]->id,
			array(
				WP_MySQL_Lexer::FROM_SYMBOL,
				WP_MySQL_Lexer::JOIN_SYMBOL,
			),
			true
		);
	}

	/**
	 * Check whether a SELECT token starts an explicit configured-database table qualifier.
	 *
	 * @param WP_Parser_Token[] $tokens Token stream.
	 * @param int               $index  Token offset.
	 * @return bool Whether the configured database qualifier should be stripped.
	 */
	private function is_configured_database_select_table_qualifier( array $tokens, int $index ): bool {
		if (
			! isset( $tokens[ $index - 1 ], $tokens[ $index + 2 ] )
			|| ! in_array( $tokens[ $index - 1 ]->id, array( WP_MySQL_Lexer::FROM_SYMBOL, WP_MySQL_Lexer::JOIN_SYMBOL ), true )
			|| ! $this->token_identifier_equals( $tokens[ $index ], $this->database )
			|| WP_MySQL_Lexer::DOT_SYMBOL !== $tokens[ $index + 1 ]->id
			|| $this->is_non_identifier_token( $tokens[ $index + 2 ] )
		) {
			return false;
		}

		return true;
	}

	/**
	 * Read recorded MySQL column metadata.
	 *
	 * @param string $table_name Table name.
	 * @return array<int,array<string,mixed>>
	 */
	private function column_metadata_rows( string $table_name, bool $temporary = false ): array {
		$cache_key = $this->metadata_table_cache_key( $table_name, $temporary );
		if ( isset( $this->column_metadata_cache[ $cache_key ] ) ) {
			return $this->column_metadata_cache[ $cache_key ];
		}

		$this->ensure_column_metadata_table( $temporary );

		$stmt = $this->execute_column_metadata_query(
			'SELECT ordinal_position, column_name, column_type, is_nullable, column_key, column_default, extra, collation_name, comment FROM '
				. $this->connection->quote_identifier( $this->column_metadata_table_name( $temporary ) )
				. ' WHERE table_name = '
				. $this->connection->quote( $table_name )
				. ' ORDER BY ordinal_position',
			'Failed to inspect DuckDB column metadata',
			$temporary
		);

		$this->column_metadata_cache[ $cache_key ] = $stmt->fetchAll( PDO::FETCH_ASSOC );
		return $this->column_metadata_cache[ $cache_key ];
	}

	/**
	 * Check whether a SELECT references information_schema.tables.
	 *
	 * @param WP_Parser_Token[] $tokens Token stream.
	 * @return bool Whether the query needs the compatibility table.
	 */
	private function uses_information_schema_tables( array $tokens ): bool {
		for ( $index = 0; $index < count( $tokens ); ++$index ) {
			if ( null !== $this->information_schema_tables_reference_length( $tokens, $index ) ) {
				return true;
			}
		}

		return false;
	}

