			'table_name'    => 'TABLE_NAME',
			'non_unique'    => 'NON_UNIQUE',
			'index_schema'  => 'INDEX_SCHEMA',
			'index_name'    => 'INDEX_NAME',
			'seq_in_index'  => 'SEQ_IN_INDEX',
			'column_name'   => 'COLUMN_NAME',
			'collation'     => 'COLLATION',
			'cardinality'   => 'CARDINALITY',
			'sub_part'      => 'SUB_PART',
			'packed'        => 'PACKED',
			'nullable'      => 'NULLABLE',
			'index_type'    => 'INDEX_TYPE',
			'comment'       => 'COMMENT',
